rules.App formula:
=SUM(
  SELECT(
    Cash Pool Contributions[Net Contribution],
    [Contribution Date] <= [_THISROW].[Payment Date]
  )
)

=SUM(
  SELECT(
    Cash Pool Contributions[Net Contribution],
    AND(
      [Contribution Date] <= [_THISROW].[Payment Date],
      [Ref Partner].[Partner Role] = "A"
    )
  )
)

=SUM(
  SELECT(
    Cash Pool Contributions[Net Contribution],
    AND(
      [Contribution Date] <= [_THISROW].[Payment Date],
      [Ref Partner].[Partner Role] = "B"
    )
  )
)

definition.Row filter condition:
=AND(
  [Status] = "Posted",
  OR(ISNOTBLANK([Receipt Image]), ISNOTBLANK([Uploaded Receipt])),
  COUNT(
    INTERSECT(
      SELECT([Related Payment Allocations][Ref Charge], [Allocated Amount] > 0),
      [Ref Borrower].[Todays Collection Charges]
    )
  ) > 0
)

